145	//*****************************************************************************
146	//********************************** SPI bus **********************************
147	//*****************************************************************************
148	// STM32 SPI transfer mode:
149	// in 8 bit mode:
150	// if you write *(uint8_t*)(&SPI1->DR)  = (uint8_t) data, then data send as << data
151	// if you write *(uint16_t*)(&SPI1->DR) =(uint16_t) data, then data send as << dataLoByte, after send dataHiByte
152	// in 16 bit mode
153	// if you write *(uint16_t*)(&SPI1->DR) =(uint16_t) data, then data send as << data
154	
155	// SPI init in 8 bit mode
156	#define SPI_CR2_8BIT  0x0700
157	#define SPI_CR2_16BIT 0x0F00
158	
159	// SPI bus activity macros
160	
161	// The RXNE flag is set depending on the FRXTH bit value in the SPIx_CR2 register:
162	// • If FRXTH is set, RXNE goes high and stays high until the RXFIFO level is greater or equal to 1/4 (8-bit).
163	#define SPI_RX_IS_NOT_EMPTY  (SPI1->SR&SPI_SR_RXNE)
164	#define SPI_RX_IS_EMPTY     (((SPI1->SR&SPI_SR_RXNE) == 0))
165	
166	// The TXE flag is set when transmission TXFIFO has enough space to store data to send.
167	// 0: Tx buffer not empty, bit is cleared automatically when the TXFIFO level becomes greater than 1/2
168	// 1: Tx buffer empty, flag goes high and stays high until the TXFIFO level is lower or equal to 1/2 of the FIFO depth
169	#define SPI_TX_IS_NOT_EMPTY  (((SPI1->SR&(SPI_SR_TXE)) == 0))
170	#define SPI_TX_IS_EMPTY     (SPI1->SR&SPI_SR_TXE)
171	
172	// When BSY is set, it indicates that a data transfer is in progress on the SPI (the SPI bus is busy).
173	#define SPI_IS_BUSY     (SPI1->SR & SPI_SR_BSY)
174	
175	// SPI send data macros
176	#define SPI_WRITE_8BIT(data)  *(__IO uint8_t*)(&SPI1->DR) = (uint8_t) data
177	#define SPI_WRITE_16BIT(data) SPI1->DR = data
178	
179	// SPI read data macros
180	#define SPI_READ_DATA        SPI1->DR
