212	static void dmaStreamFlush(uint32_t len)
213	{
214	  while (len) {
215	    // DMA data transfer limited by 65535
216	    uint16_t tx_size = len > 65535 ? 65535 : len;
217	    dmaStreamSetTransactionSize(dmatx, tx_size);
218	    dmaStreamEnable(dmatx);
219	    len -= tx_size;
220	    dmaWaitCompletion(dmatx);
221	  }
222	}
223	#endif
