225	static void spi_init(void)
226	{
227	  rccEnableSPI1(FALSE);
228	  SPI1->CR1 = 0;
229	  SPI1->CR1 = SPI_CR1_MSTR       // SPI is MASTER
230	            | SPI_CR1_SSM        // Software slave management (The external NSS pin is free for other application uses)
231	            | SPI_CR1_SSI;       // Internal slave select (This bit has an effect only when the SSM bit is set. Allow use NSS pin as I/O)
232	//          | SPI_CR1_BR_1;      // Baud rate control
233	
234	  SPI1->CR2 = SPI_CR2_8BIT       // SPI data size, set to 8 bit
235	            | SPI_CR2_FRXTH;     // SPI_SR_RXNE generated every 8 bit data
236	//          | SPI_CR2_SSOE;      //
237	
238	#ifdef __USE_DISPLAY_DMA__
239	  // Tx DMA init
240	  dmaStreamAllocate(dmatx, STM32_SPI_SPI1_IRQ_PRIORITY, (stm32_dmaisr_t)spi_lld_serve_tx_interrupt, NULL);
241	  dmaStreamSetPeripheral(dmatx, &SPI1->DR);
242	  // Rx DMA init
243	  dmaStreamAllocate(dmarx, STM32_SPI_SPI1_IRQ_PRIORITY, (stm32_dmaisr_t)spi_lld_serve_rx_interrupt, NULL);
244	  dmaStreamSetPeripheral(dmarx, &SPI1->DR);
245	  // Enable DMA on SPI
246	  SPI1->CR2|= SPI_CR2_TXDMAEN    // Tx DMA enable
247	           |  SPI_CR2_RXDMAEN;   // Rx DMA enable
248	#endif
249	  SPI1->CR1|= SPI_CR1_SPE;       //SPI enable
250	}
