252	// Disable inline for this function
253	static void __attribute__ ((noinline)) send_command(uint8_t cmd, uint8_t len, const uint8_t *data)
254	{
255	  CS_LOW;
256	  //while (SPI_TX_IS_NOT_EMPTY);
257	  DC_CMD;
258	  SPI_WRITE_8BIT(cmd);
259	  // Need wait transfer complete and set data bit
260	  while (SPI_IS_BUSY)
261	    ;
262	  // Send command data (if need)
263	  DC_DATA;
264	  while (len-- > 0) {
265	    while (SPI_TX_IS_NOT_EMPTY)
266	      ;
267	    SPI_WRITE_8BIT(*data++);
268	  }
269	  //CS_HIGH;
270	}
