336	void ili9341_init(void)
337	{
338	  spi_init();
339	  DC_DATA;
340	  RESET_ASSERT;
341	  chThdSleepMilliseconds(10);
342	  RESET_NEGATE;
343	  const uint8_t *p;
344	  for (p = ili9341_init_seq; *p; ) {
345	    send_command(p[0], p[1], &p[2]);
346	    p += 2 + p[1];
347	    chThdSleepMilliseconds(5);
348	  }
349	}
