352	void ili9341_fill(int x, int y, int w, int h, int color)
353	{
354	//uint8_t xx[4] = { x >> 8, x, (x+w-1) >> 8, (x+w-1) };
355	//uint8_t yy[4] = { y >> 8, y, (y+h-1) >> 8, (y+h-1) };
356	  uint32_t xx = __REV16(x | ((x + w - 1) << 16));
357	  uint32_t yy = __REV16(y | ((y + h - 1) << 16));
358	  send_command(ILI9341_COLUMN_ADDRESS_SET, 4, (uint8_t*)&xx);
359	  send_command(ILI9341_PAGE_ADDRESS_SET, 4, (uint8_t*)&yy);
360	  send_command(ILI9341_MEMORY_WRITE, 0, NULL);
361	  int32_t len = w * h;
362	  while (len-- > 0) {
363	    while (SPI_TX_IS_NOT_EMPTY)
364	      ;
365	  SPI_WRITE_16BIT(color);
366	  }
367	}
