387	static uint8_t ssp_sendrecvdata(void)
388	{
389	  // Start RX clock (by sending data)
390	  SPI_WRITE_8BIT(0);
391	  while (SPI_RX_IS_EMPTY && SPI_IS_BUSY)
392	    ;
393	  return SPI_READ_DATA;
394	}
