396	void ili9341_read_memory(int x, int y, int w, int h, int len, uint16_t *out)
397	{
398	  // uint8_t xx[4] = { x >> 8, x, (x+w-1) >> 8, (x+w-1) };
399	  // uint8_t yy[4] = { y >> 8, y, (y+h-1) >> 8, (y+h-1) };
400	  uint32_t xx = __REV16(x | ((x + w - 1) << 16));
401	  uint32_t yy = __REV16(y | ((y + h - 1) << 16));
402	  send_command(ILI9341_COLUMN_ADDRESS_SET, 4, (uint8_t *)&xx);
403	  send_command(ILI9341_PAGE_ADDRESS_SET, 4, (uint8_t*)&yy);
404	  send_command(ILI9341_MEMORY_READ, 0, NULL);
405	
406	  // Skip data from rx buffer
407	  while (SPI_RX_IS_NOT_EMPTY)
408	    (void) SPI_READ_DATA;
409	  // require 8bit dummy clock
410	  ssp_sendrecvdata();
411	  while (len-- > 0) {
412	    // read data is always 18bit
413	    uint8_t r = ssp_sendrecvdata();
414	    uint8_t g = ssp_sendrecvdata();
415	    uint8_t b = ssp_sendrecvdata();
416	    *out++ = RGB565(r, g, b);
417	  }
418	  CS_HIGH;
419	}
