425	// Fill region by some color
426	void ili9341_fill(int x, int y, int w, int h, int color)
427	{
428	  uint32_t xx = __REV16(x | ((x + w - 1) << 16));
429	  uint32_t yy = __REV16(y | ((y + h - 1) << 16));
430	  send_command(ILI9341_COLUMN_ADDRESS_SET, 4, (uint8_t *)&xx);
431	  send_command(ILI9341_PAGE_ADDRESS_SET, 4, (uint8_t *)&yy);
432	  send_command(ILI9341_MEMORY_WRITE, 0, NULL);
433	
434	  dmaStreamSetMemory0(dmatx, &color);
435	  dmaStreamSetMode(dmatx, txdmamode | STM32_DMA_CR_PSIZE_HWORD | STM32_DMA_CR_MSIZE_HWORD);
436	  dmaStreamFlush(w * h);
437	}
