459	{
460	  uint32_t xx = __REV16(x | ((x + w - 1) << 16));
461	  uint32_t yy = __REV16(y | ((y + h - 1) << 16));
462	  send_command(ILI9341_COLUMN_ADDRESS_SET, 4, (uint8_t *)&xx);
463	  send_command(ILI9341_PAGE_ADDRESS_SET, 4, (uint8_t *)&yy);
464	  send_command(ILI9341_MEMORY_WRITE, 0, NULL);
465	
466	  // Init Tx DMA mem->spi, set size, mode (spi and mem data size is 16 bit)
467	  dmaStreamSetMemory0(dmatx, spi_buffer);
468	  dmaStreamSetMode(dmatx, txdmamode | STM32_DMA_CR_PSIZE_HWORD |
469	                              STM32_DMA_CR_MSIZE_HWORD | STM32_DMA_CR_MINC);
470	  dmaStreamFlush(w * h);
471	}
472	
473	// Copy screen data to buffer
474	// Warning!!! buffer size must be greater then 3*len + 1 bytes
475	void ili9341_read_memory(int x, int y, int w, int h, int len, uint16_t *out)
476	{
477	  uint8_t dummy_tx = 0;
478	  uint8_t *rgbbuf = (uint8_t *)out;
479	  uint16_t data_size = len * 3 + 1;
480	  uint32_t xx = __REV16(x | ((x + w - 1) << 16));
481	  uint32_t yy = __REV16(y | ((y + h - 1) << 16));
482	  send_command(ILI9341_COLUMN_ADDRESS_SET, 4, (uint8_t *)&xx);
483	  send_command(ILI9341_PAGE_ADDRESS_SET, 4, (uint8_t *)&yy);
484	  send_command(ILI9341_MEMORY_READ, 0, NULL);
485	  // Skip SPI rx buffer
486	  while (SPI_RX_IS_NOT_EMPTY) (void)SPI_READ_DATA;
487	  // Init Rx DMA buffer, size, mode (spi and mem data size is 8 bit)
488	  dmaStreamSetMemory0(dmarx, rgbbuf);
489	  dmaStreamSetTransactionSize(dmarx, data_size);
490	  dmaStreamSetMode(dmarx, rxdmamode | STM32_DMA_CR_PSIZE_BYTE | STM32_DMA_CR_MSIZE_BYTE |
491	                              STM32_DMA_CR_MINC);
492	  // Init dummy Tx DMA (for rx clock), size, mode (spi and mem data size is 8 bit)
493	  dmaStreamSetMemory0(dmatx, &dummy_tx);
494	  dmaStreamSetTransactionSize(dmatx, data_size);
495	  dmaStreamSetMode(dmatx, txdmamode | STM32_DMA_CR_PSIZE_BYTE | STM32_DMA_CR_MSIZE_BYTE);
496	
497	  // Start DMA exchange
498	  dmaStreamEnable(dmatx);
499	  dmaStreamEnable(dmarx);
500	  // Wait DMA completion
501	  dmaWaitCompletion(dmatx);
502	  dmaWaitCompletion(dmarx);
503	  CS_HIGH;
504	
505	  // Parce recived data
506	  // Skip dummy 8-bit read
507	  rgbbuf++;
508	  while (len-- > 0) {
509	    uint8_t r, g, b;
510	    // read data is always 18bit
511	    r = rgbbuf[0];
512	    g = rgbbuf[1];
513	    b = rgbbuf[2];
514	    *out++ = RGB565(r, g, b);
515	    rgbbuf += 3;
516	  }
517	}
518	#endif
