542	void blit8BitWidthBitmap(uint16_t x, uint16_t y, uint16_t width, uint16_t height,
543	                         const uint8_t *bitmap) 
544	{
545	  uint16_t *buf = spi_buffer;
546	  for (uint16_t c = 0; c < height; c++) {
547	    uint8_t bits = *bitmap++;
548	    for (uint16_t r = 0; r < width; r++) {
549	      *buf++ = (0x80 & bits) ? foreground_color : background_color;
550	      bits <<= 1;
551	    }
552	  }
553	  ili9341_bulk(x, y, width, height);
